mapper.select:
SELECT a.ap_id, a.company_id, a.ap_no, a.source_module, a.source_type, a.source_id, a.source_key,
       a.partner_id, a.partner_name, a.supplier_id, a.ap_date, a.period,
       a.amount_excl_tax, a.tax_amount, a.total_amount, a.paid_amount, a.tax_rate,
       a.invoice_no, a.invoice_code, a.invoice_date, a.due_date, a.payment_days, a.status,
       a.dept_id, a.user_id,
       a.create_by, a.create_time, a.update_by, a.update_time, a.remark
FROM fin_ap_order a


        AND a.ap_no LIKE CONCAT('%', #{apNo}, '%')


        AND a.partner_name LIKE CONCAT('%', #{partnerName}, '%')


        AND a.period = #{period}


        AND a.status = #{status}


        AND a.source_module = #{sourceModule}


        AND a.ap_date >= #{params.beginApDate}


        AND a.ap_date <= #{params.endApDate}

    AND a.del_flag = '0'

        AND ${params.dataScope}


ORDER BY a.ap_date DESC, a.ap_id DESC


WHERE source_module = #{sourceModule}
  AND source_type   = #{sourceType}
  AND source_id     = #{sourceId}
  AND del_flag      = '0'
LIMIT 1

mapper.update:
UPDATE fin_ap_order
partner_id = #{partnerId}, partner_name = #{partnerName}, ap_date = #{apDate}, period = #{period}, due_date = #{dueDate}, payment_days = #{paymentDays}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
WHERE ap_id = #{apId}

UPDATE fin_ap_order SET del_flag = '2', update_time = sysdate() WHERE ap_id IN
#{id}
AND status != 'SETTLED'
